#!/usr/bin/env bash
# -----------------------------------------------------------------------------
# GENERATED by micro-os-scaffold. Run CTest cases for one configuration.
#
#   tests/test.sh [configuration] [test ...] [options]
#
# A test is named by its selection id (4.4.12) or by its application
# directory name (smp-mat-test-ram, my-new-test). With no test, the tests
# listed for the configuration in scripts/selected-tests.txt are run.
#
#   ./test.sh                         the selected tests
#   ./test.sh <config> 4.4.12         one selected test, by selection id
#   ./test.sh <config> my-new-test    any test directory, by name
#   ./test.sh --all                   every test registered in the build tree
#   ./test.sh --list                  list the registered CTest cases
#   ./test.sh --hwd                   include the hardware (-hwd) cases
#   ./test.sh --hwd-only              only the hardware (-hwd) cases
#   ./test.sh --regex '<re>'          ad-hoc CTest regular expression
#   ./test.sh --no-build              do not build first
#
# The build tree is configured and built first (tests/build.sh), so a new
# source file or a new test directory is picked up without another step.
# Hardware cases need the board and the probe; they run only when asked for
# (--hwd), or when the requested test has no other image.
# -----------------------------------------------------------------------------
set -uo pipefail
HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
source "$HERE/scripts/env.sh"
DEFAULT_CONFIG='__DEFAULT_CONFIG__'
MAP="$HERE/scripts/selected-tests.txt"
CONFIG=""
WANTED=()
REGEX=""
HWD=0
ALL=0
LIST=0
BUILD=1
while [[ $# -gt 0 ]]; do
  case "$1" in
    --hwd) HWD=1 ;;
    --hwd-only) HWD=2 ;;
    --all) ALL=1 ;;
    --list) LIST=1 ;;
    --no-build) BUILD=0 ;;
    --regex) [[ $# -ge 2 ]] || { echo "--regex needs a value" >&2; exit 2; }; REGEX="$2"; shift ;;
    -h|--help) sed -n '2,26p' "$0"; exit 0 ;;
    -*) echo "Unknown option: $1" >&2; exit 2 ;;
    *)
      if grep -q "^    $1) PLATFORM=" "$HERE/build.sh" 2>/dev/null; then
        CONFIG="$1"
      else
        WANTED+=("$1")
      fi
      ;;
  esac
  shift
done
CONFIG="${CONFIG:-$DEFAULT_CONFIG}"
BUILD_DIR="$HERE/build/$CONFIG"

if [[ "$BUILD" == "1" ]]; then
  "$HERE/build.sh" "$CONFIG" || exit $?
fi
[[ -d "$BUILD_DIR" ]] || { echo "No build tree: $BUILD_DIR (run tests/build.sh $CONFIG)" >&2; exit 2; }

# Every CTest case registered in the build tree, one name per line.
REGISTERED="$(ctest --test-dir "$BUILD_DIR" -N | sed -n 's/^ *Test *#[0-9]*: *\([^ ]*\).*/\1/p')"

if [[ "$LIST" == "1" ]]; then
  echo "CTest cases of $CONFIG (selected ones are marked *):"
  while IFS= read -r name; do
    [[ -n "$name" ]] || continue
    mark=" "
    if [[ -f "$MAP" ]] && awk -F "\t" -v c="$CONFIG" -v n="$name" \
        '!/^#/ && $1 == c { k = split($3, a, ","); for (i = 1; i <= k; i++) if (a[i] == n) f = 1 } END { exit !f }' "$MAP"; then
      mark="*"
    fi
    echo "  $mark $name"
  done <<< "$REGISTERED"
  exit 0
fi

if [[ -n "$REGEX" ]]; then
  exec ctest --test-dir "$BUILD_DIR" -V -R "$REGEX"
fi

# CTest names recorded for a selection id, or for the whole configuration.
mapped() {
  [[ -f "$MAP" ]] || return 0
  awk -F "\t" -v c="$CONFIG" -v s="${1:-}" \
    '!/^#/ && $1 == c && (s == "" || $2 == s) { k = split($3, a, ","); for (i = 1; i <= k; i++) print a[i] }' "$MAP"
}

# CTest names of an application directory: <platform>-<app>-<variant>.
by_app() {
  grep -E -- "-$1-(qemu|hwd|host)\$|-$1\$" <<< "$REGISTERED" || true
}

NAMES=()
if [[ "$ALL" == "1" ]]; then
  while IFS= read -r name; do [[ -n "$name" ]] && NAMES+=("$name"); done <<< "$REGISTERED"
elif [[ ${#WANTED[@]} -gt 0 ]]; then
  for item in "${WANTED[@]}"; do
    found="$(mapped "$item")"
    [[ -n "$found" ]] || found="$(by_app "$item")"
    if [[ -z "$found" ]]; then
      echo "No test '$item' in $CONFIG. Registered cases: ./test.sh $CONFIG --list" >&2
      exit 2
    fi
    while IFS= read -r name; do [[ -n "$name" ]] && NAMES+=("$name"); done <<< "$found"
  done
else
  while IFS= read -r name; do [[ -n "$name" ]] && NAMES+=("$name"); done < <(mapped)
  [[ ${#NAMES[@]} -gt 0 ]] || { echo "No selected tests for $CONFIG in $MAP (try --all or --list)." >&2; exit 2; }
fi

# Hardware cases run only with --hwd or --hwd-only, unless nothing else was
# asked for.
RUN=()
if [[ "$HWD" == "2" ]]; then
  for name in "${NAMES[@]}"; do
    [[ "$name" == *-hwd ]] && RUN+=("$name")
  done
  [[ ${#RUN[@]} -gt 0 ]] || { echo "No hardware (-hwd) case among: ${NAMES[*]}" >&2; exit 2; }
elif [[ "$HWD" == "1" ]]; then
  RUN=("${NAMES[@]}")
else
  for name in "${NAMES[@]}"; do
    [[ "$name" == *-hwd ]] || RUN+=("$name")
  done
  if [[ ${#RUN[@]} -eq 0 ]]; then
    RUN=("${NAMES[@]}")
    echo "Only hardware (-hwd) cases match: the board and the probe must be connected."
  fi
fi

# Exact names, escaped for the CTest regular expression.
PATTERN=""
for name in "${RUN[@]}"; do
  escaped="$(sed 's/[][\.^$*+?(){}|]/\\&/g' <<< "$name")"
  PATTERN="${PATTERN:+$PATTERN|}$escaped"
done
echo "Running ${#RUN[@]} CTest case(s): ${RUN[*]}"
exec ctest --test-dir "$BUILD_DIR" -V -R "^(${PATTERN})\$"
